fn longest(v: &Vec[Str]) -> Str {
  if v.len() == 0 { return ""; }
  var max_idx = 0;
  var i = 1;
  while i < v.len() {
    if v[i].len() > v[max_idx].len() {
      max_idx = i;
    }
    i = i + 1;
  }
  return v[max_idx];
}

fn count_contains(v: &Vec[Str], sub: Str) -> Int {
  var count = 0;
  var i = 0;
  while i < v.len() {
    if v[i].contains(sub) {
      count = count + 1;
    }
    i = i + 1;
  }
  return count;
}

fn main() -> Int {
  let words = Vec[Str]();
  words.push("hello");
  words.push("world");
  words.push("xiom");
  let long = longest(&words);
  return long.len();
}
